_CORE_SRC = '# Action format: [(from_node, to_node, count), ...]\n# Revenue: capacity_i * demand / max(total_capacity, demand).\n# Cost: 2.0 per drone not on its own base after that turn\'s moves.\n\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 100\nDRONES_PER_PLAYER = 30\nDRONE_CAPACITY = 5\nUPKEEP = 2.0\n\n\ndef build_map(n, edges):\n    """Return sorted adjacency lists, all-pairs distances, and deterministic next hops."""\n    adj = [[] for _ in range(n)]\n    for u, v in edges:\n        if 0 <= u < n and 0 <= v < n and u != v:\n            adj[u].append(v)\n            adj[v].append(u)\n    adj = [sorted(set(row)) for row in adj]\n\n    distances = []\n    next_hop = []\n    for start in range(n):\n        dist = [-1] * n\n        first = [-1] * n\n        dist[start] = 0\n        queue = deque([start])\n        while queue:\n            u = queue.popleft()\n            for v in adj[u]:\n                if dist[v] != -1:\n                    continue\n                dist[v] = dist[u] + 1\n                first[v] = v if u == start else first[u]\n                queue.append(v)\n        distances.append(dist)\n        next_hop.append(first)\n    return adj, distances, next_hop\n\n\ndef served(drones, opposing_drones, demand):\n    """The spec\'s revenue payout for one player at one node."""\n    own_capacity = drones * DRONE_CAPACITY\n    other_capacity = opposing_drones * DRONE_CAPACITY\n    total_capacity = own_capacity + other_capacity\n    denominator = max(total_capacity, demand)\n    if denominator <= 0:\n        return 0.0, 0.0\n    return (own_capacity * demand / denominator,\n            other_capacity * demand / denominator)\n\n\ndef marginal_margin(own_count, opponent_count, demand):\n    """Change in score margin from adding one own drone at a node."""\n    before_own, before_opp = served(own_count, opponent_count, demand)\n    after_own, after_opp = served(own_count + 1, opponent_count, demand)\n    return (after_own - before_own) + (before_opp - after_opp)\n\n\ndef forecast_value(forecast, node, offset):\n    """Use exact forecast values, then conservatively extend the last value."""\n    values = forecast[node]\n    if not values:\n        return 0.0\n    if offset < len(values):\n        return max(0.0, float(values[offset]))\n    # Demand generally grows over the game, but avoid extrapolating a short spike.\n    last = max(0.0, float(values[-1]))\n    if len(values) >= 2:\n        previous = max(0.0, float(values[-2]))\n        trend = max(-0.05, min(0.05, (last - previous) / max(1.0, previous)))\n        steps = offset - len(values) + 1\n        return last * (1.0 + trend) ** min(steps, 8)\n    return last\n\n\ndef make_plan(obs, distances, player_base):\n    """Greedily assign available drones to profitable node slots, including travel delay."""\n    n = int(obs["n_nodes"])\n    turn = int(obs.get("turn", 0))\n    remaining_turns = max(0, N_TURNS - turn)\n    own = [max(0, int(x)) for x in obs.get("player_drones", [0] * n)]\n    opponent = [max(0, int(x)) for x in obs.get("opponent_drones", [0] * n)]\n    forecast = obs.get("demand_forecast", [[] for _ in range(n)])\n\n    # Sources are counts at the start of this turn. Drones assigned to the base\n    # are the uncommitted, cost-free remainder.\n    sources = own[:]\n    target = [0] * n\n    demand_nodes = [i for i in range(n) if i != player_base and i < len(forecast)]\n\n    for _ in range(min(DRONES_PER_PLAYER, sum(sources))):\n        best_score = 0.0\n        best = None\n        for node in demand_nodes:\n            count = target[node]\n            for source in range(n):\n                if sources[source] <= 0:\n                    continue\n                hops = distances[source][node]\n                if hops < 0:\n                    continue\n                # A drone arriving after h moves is present for this turn when h=1.\n                first_paid_offset = max(0, hops - 1)\n                if first_paid_offset >= remaining_turns:\n                    continue\n\n                score = 0.0\n                for offset in range(first_paid_offset, remaining_turns):\n                    demand = forecast_value(forecast, node, offset)\n                    score += marginal_margin(count, opponent[node], demand)\n                # Every turn after its first move, including travel turns, incurs upkeep.\n                deployed_turns = remaining_turns\n                if source == player_base and hops == 0:\n                    deployed_turns = 0\n                score -= UPKEEP * deployed_turns\n\n                candidate = (score, -node, -source)\n                if best is None or candidate > best:\n                    best = candidate\n                    best_score = score\n        if best is None or best_score <= 0.0:\n            break\n        node = -best[1]\n        source = -best[2]\n        sources[source] -= 1\n        target[node] += 1\n\n    target[player_base] += sum(sources)\n    return target\n\n\ndef plan_to_legal_action(obs, target, adj, distances, next_hop):\n    """Move surplus drones one legal edge toward target deficits."""\n    n = int(obs["n_nodes"])\n    own = [max(0, int(x)) for x in obs.get("player_drones", [0] * n)]\n    surplus = [max(0, own[i] - target[i]) for i in range(n)]\n    deficit = [max(0, target[i] - own[i]) for i in range(n)]\n\n    pairs = []\n    for source in range(n):\n        if surplus[source] <= 0:\n            continue\n        for destination in range(n):\n            if deficit[destination] > 0 and distances[source][destination] > 0:\n                pairs.append((distances[source][destination], source, destination))\n    pairs.sort()\n\n    planned = {}\n    for _, source, destination in pairs:\n        count = min(surplus[source], deficit[destination])\n        if count <= 0:\n            continue\n        hop = next_hop[source][destination]\n        if hop < 0 or hop not in adj[source]:\n            continue\n        planned[(source, hop)] = planned.get((source, hop), 0) + count\n        surplus[source] -= count\n        deficit[destination] -= count\n\n    # Validate each emitted move against start-of-turn counts and graph adjacency.\n    available = own[:]\n    action = []\n    for (source, destination), count in sorted(planned.items()):\n        if (0 <= source < n and 0 <= destination < n\n                and destination in adj[source] and count > 0\n                and count <= available[source]):\n            action.append((int(source), int(destination), int(count)))\n            available[source] -= count\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = int(player_id)\n        self._map_key = None\n        self._adj = None\n        self._distances = None\n        self._next_hop = None\n        self._bad_reports = 0\n\n    def act(self, obs):\n        start_time = time.perf_counter()\n        n = int(obs.get("n_nodes", 0))\n        edges = obs.get("edges", [])\n        player_base = int(obs.get("player_base", 0))\n\n        map_key = (n, tuple(tuple(edge) for edge in edges))\n        if map_key != self._map_key:\n            self._adj, self._distances, self._next_hop = build_map(n, edges)\n            self._map_key = map_key\n\n        if (not bool(obs.get("action_format_correct_last_turn", True))\n                or int(obs.get("n_invalid_actions_last_turn", 0)) > 0):\n            self._bad_reports += 1\n        else:\n            self._bad_reports = 0\n\n        # A valid plan is computed directly from the visible start-of-turn state.\n        target = make_plan(obs, self._distances, player_base)\n        action = plan_to_legal_action(\n            obs, target, self._adj, self._distances, self._next_hop\n        )\n\n        # The built-in planning work is small for this game\'s maps. Keep the\n        # deadline check here so future refinements can stop without delaying return.\n        if time.perf_counter() - start_time > 0.6 * TIME_BUDGET:\n            return []\n        return action\n'
